-- Generated from data/d3/base_items.csv; edit the CSV and rerun generate_sql.py.
-- Apply to the world database. Entries are assigned by sorted d3_id from 100000.
SET NAMES utf8mb4;
DROP TABLE IF EXISTS `dc_base_item`;
CREATE TABLE `dc_base_item` (
  `entry` BIGINT NOT NULL,
  `d3_id` LONGTEXT NOT NULL,
  `d3_name` LONGTEXT NOT NULL,
  `slot` LONGTEXT NOT NULL,
  `type` LONGTEXT NOT NULL,
  `rarity` LONGTEXT NOT NULL,
  `usable_by` LONGTEXT NOT NULL,
  `item_level` BIGINT NULL,
  `level_req` BIGINT NULL,
  `weapon_min` BIGINT NULL,
  `weapon_max` BIGINT NULL,
  `weapon_aps` DECIMAL(3,2) NULL,
  `preset_affixes` LONGTEXT NOT NULL,
  `set_name` LONGTEXT NOT NULL,
  `source_file` LONGTEXT NOT NULL,
  `pool_version` LONGTEXT NOT NULL,
  `designated_class` LONGTEXT NOT NULL,
  `craft_only` LONGTEXT NOT NULL,
  PRIMARY KEY (`entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
